messages.content:
The reason your transcription doesn't work is that **there is no actual audio recording** — the current code only creates an empty placeholder file and the Whisper C++ side is a stub. When you press the record button, no audio is captured, and the “transcription” is just a hard‑coded test string.

I’ll now add a real audio recorder that captures from the microphone as 16 kHz mono PCM WAV, and wire it into the ViewModel. This will make the recording part functional; transcription will still show the stub until you integrate the real whisper.cpp library.

---

## ✅ What I’m adding / fixing

1. **`AudioRecorderHelper.kt`** – A class that uses Android’s `AudioRecord` to record raw PCM and writes a valid WAV file.
2. **`MainViewModel.kt`** – Replaces the placeholder recording logic with the new helper.
3. **Permission handling** – Ensures the microphone permission is properly used before recording starts.

---

<file path="app/src/main/java/com/noteflowai/app/data/AudioRecorderHelper.kt">
```kotlin
package com.noteflowai.app.data

import android.media.AudioFormat
import android.media.AudioRecord
import android.media.MediaRecorder
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileOutputStream
import java.io.IOException
import java.nio.ByteBuffer
import java.nio.ByteOrder

/**
 * Records audio from the microphone and writes a valid WAV file (16kHz, mono, 16-bit PCM).
 */
class AudioRecorderHelper {

    private var audioRecord: AudioRecord? = null
    private var isRecording = false
    private val sampleRate = 16000
    private val channelConfig = AudioFormat.CHANNEL_IN_MONO
    private val audioFormat = AudioFormat.ENCODING_PCM_16BIT

    /**
     * Start recording to the given file path (WAV format).
     * The file will be overwritten if it exists.
     */
    suspend fun startRecording(outputFile: File) {
        withContext(Dispatchers.IO) {
            val bufferSize = AudioRecord.getMinBufferSize(
                sampleRate,
                channelConfig,
                audioFormat
            )
            if (bufferSize == AudioRecord.ERROR || bufferSize == AudioRecord.ERROR_BAD_VALUE) {
                throw IllegalStateException("Invalid buffer size")
            }

            audioRecord = AudioRecord(
                MediaRecorder.AudioSource.MIC,
                sampleRate,
                channelConfig,
                audioFormat,
                bufferSize
            )

            if (audioRecord?.state != AudioRecord.STATE_INITIALIZED) {
                audioRecord?.release()
                throw IllegalStateException("AudioRecord failed to initialize")
            }

            audioRecord?.startRecording()
            isRecording = true

            val pcmData = mutableListOf<ByteArray>()

            // Record until stopRecording() is called
            while (isRecording) {
                val buffer = ByteArray(bufferSize)
                val read = audioRecord?.read(buffer, 0, buffer.size) ?: -1
                if (read > 0) {
                    pcmData.add(buffer.copyOf(read))
                }
            }

            audioRecord?.stop()
            audioRecord?.release()
            audioRecord = null

            // Write WAV file
            writeWav(outputFile, pcmData.toByteArray())
        }
    }

    fun stopRecording() {
        isRecording = false
    }

    private suspend fun writeWav(file: File, pcmData: ByteArray) {
        withContext(Dispatchers.IO) {
            try {
                FileOutputStream(file).use { fos ->
                    val totalAudioLen = pcmData.size
                    val totalDataLen = totalAudioLen + 36
                    val byteRate = sampleRate * 2 // 16-bit mono
                    val channels = 1
                    val bitsPerSample = 16

                    val header = ByteArray(44)
                    // RIFF header
                    header[0] = 'R'.code.toByte()
                    header[1] = 'I'.code.toByte()
                    header[2] = 'F'.code.toByte()
                    header[3] = 'F'.code.toByte()
                    header[4] = (totalDataLen and 0xff).toByte()
                    header[5] = ((totalDataLen shr 8) and 0xff).toByte()
                    header[6] = ((totalDataLen shr 16) and 0xff).toByte()
                    header[7] = ((totalDataLen shr 24) and 0xff).toByte()
                    header[8] = 'W'.code.toByte()
                    header[9] = 'A'.code.toByte()
                    header[10] = 'V'.code.toByte()
                    header[11] = 'E'.code.toByte()
                    // fmt subchunk
                    header[12] = 'f'.code.toByte()
                    header[13] = 'm'.code.toByte()
                    header[14] = 't'.code.toByte()
                    header[15] = ' '.code.toByte()
                    header[16] = 16 // subchunk size
                    header[17] = 0
                    header[18] = 0
                    header[19] = 0
                    header[20] = 1 // PCM format
                    header[21] = 0
                    header[22] = channels.toByte()
                    header[23] = 0
                    header[24] = (sampleRate and 0xff).toByte()
                    header[25] = ((sampleRate shr 8) and 0xff).toByte()
                    header[26] = ((sampleRate shr 16) and 0xff).toByte()
                    header[27] = ((sampleRate shr 24) and 0xff).toByte()
                    header[28] = (byteRate and 0xff).toByte()
                    header[29] = ((byteRate shr 8) and 0xff).toByte()
                    header[30] = ((byteRate shr 16) and 0xff).toByte()
                    header[31] = ((byteRate shr 24) and 0xff).toByte()
                    header[32] = (channels * bitsPerSample / 8).toByte() // block align
                    header[33] = 0
                    header[34] = bitsPerSample.toByte()
                    header[35] = 0
                    // data subchunk
                    header[36] = 'd'.code.toByte()
                    header[37] = 'a'.code.toByte()
                    header[38] = 't'.code.toByte()
                    header[39] = 'a'.code.toByte()
                    header[40] = (totalAudioLen and 0xff).toByte()
                    header[41] = ((totalAudioLen shr 8) and 0xff).toByte()
                    header[42] = ((totalAudioLen shr 16) and 0xff).toByte()
                    header[43] = ((totalAudioLen shr 24) and 0xff).toByte()

                    fos.write(header)
                    fos.write(pcmData)
                }
            } catch (e: IOException) {
                e.printStackTrace()
            }
        }
    }

    /**
     * Utility to concatenate list of byte arrays into a single array.
     */
    private fun List<ByteArray>.toByteArray(): ByteArray {
        val totalSize = this.sumOf { it.size }
        val result = ByteArray(totalSize)
        var offset = 0
        for (array in this) {
            System.arraycopy(array, 0, result, offset, array.size)
            offset += array.size
        }
        return result
    }
}
```
