package com.noteflowai.app.viewmodel

import android.app.Application
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.noteflowai.app.data.AudioRecorderHelper
import com.noteflowai.app.data.NoteFile
import com.noteflowai.app.data.NoteRepository
import com.noteflowai.app.whisper.WhisperBridge
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileOutputStream
import java.text.SimpleDateFormat
import java.util.*

class MainViewModel(application: Application) : AndroidViewModel(application) {

    private val repository = NoteRepository(application)
    private val whisperBridge = WhisperBridge()
    private val audioRecorder = AudioRecorderHelper()

    /** True when Whisper engine is loaded and ready to transcribe. */
    var isInitialized by mutableStateOf(false)
        private set

    /** True when a model file is being copied / loaded. */
    var isModelLoading by mutableStateOf(false)
        private set

    /** Error message shown to the user, e.g. missing model or permission denied. */
    var errorMessage by mutableStateOf("")
        private set

    // Recording state
    var isRecording by mutableStateOf(false)
        private set
    var isTranscribing by mutableStateOf(false)
        private set
    var transcriptionText by mutableStateOf("")
        private set
    var isTranscribeMode by mutableStateOf(true)
        private set

    // Settings
    val currentModel = mutableStateOf("tiny")
    val currentLanguage = mutableStateOf("English")

    // Notes
    val savedNotes: StateFlow<List<NoteFile>> = repository.notesFlow
    val savedNotesCount = mutableStateOf(0)
    var selectedNote by mutableStateOf<NoteFile?>(null)
        private set

    private var currentAudioFile: File? = null
    private var currentModelPath: String = ""
    private val modelsDir = File(application.filesDir, "models").also { it.mkdirs() }

    init {
        viewModelScope.launch {
            repository.notesFlow.collect { notes ->
                savedNotesCount.value = notes.size
            }
        }
        loadDefaultModel()
    }

    /** Copies and initializes the default model, sets errorMessage if impossible. */
    private fun loadDefaultModel() {
        viewModelScope.launch {
            withContext(Dispatchers.IO) {
                modelsDir.mkdirs()
                if (!copyModelFromAssets(currentModel.value)) {
                    withContext(Dispatchers.Main) {
                        isInitialized = false
                        errorMessage = "Whisper model file not found. Please add ggml-${currentModel.value}.bin to assets/models/"
                    }
                    return@withContext
                }
                initEngine()
            }
        }
    }

    /** Copies a GGML model from assets/models/ to internal storage and returns success. */
    private suspend fun copyModelFromAssets(model: String): Boolean {
        val assetPath = "models/ggml-$model.bin"
        val destFile = File(modelsDir, "ggml-$model.bin")
        if (destFile.exists()) {
            currentModelPath = destFile.absolutePath
            return true
        }
        return try {
            getApplication<Application>().assets.open(assetPath).use { input ->
                FileOutputStream(destFile).use { output ->
                    input.copyTo(output)
                }
            }
            currentModelPath = destFile.absolutePath
            true
        } catch (e: Exception) {
            false
        }
    }

    /** Calls whisperBridge.initialize and sets isInitialized or errorMessage. */
    private suspend fun initEngine() {
        withContext(Dispatchers.IO) {
            if (currentModelPath.isEmpty()) return@withContext
            val ok = whisperBridge.initialize(currentModelPath)
            withContext(Dispatchers.Main) {
                isInitialized = ok
                if (!ok) errorMessage = "Failed to load Whisper model. File may be corrupt."
                else errorMessage = ""
            }
        }
    }

    /** Called when the user changes the model in settings. */
    fun setModel(model: String) {
        currentModel.value = model
        // Reload the new model
        viewModelScope.launch {
            isModelLoading = true
            withContext(Dispatchers.IO) {
                if (!copyModelFromAssets(model)) {
                    withContext(Dispatchers.Main) {
                        errorMessage = "Model file for $model not found. Please add ggml-$model.bin to assets/models/"
                        isModelLoading = false
                    }
                    return@withContext
                }
                initEngine()
                isModelLoading = false
            }
        }
    }

    fun setLanguage(language: String) {
        currentLanguage.value = language
    }

    fun setMode(transcribe: Boolean) {
        isTranscribeMode = transcribe
    }

    fun startRecording() {
        if (!isInitialized) {
            errorMessage = "Whisper engine not ready."
            return
        }
        isRecording = true
        transcriptionText = ""
        currentAudioFile = File(getApplication<Application>().cacheDir, "temp_audio.wav")
        viewModelScope.launch(Dispatchers.IO) {
            try {
                audioRecorder.startRecording(currentAudioFile!!)
            } catch (e: Exception) {
                withContext(Dispatchers.Main) {
                    isRecording = false
                    errorMessage = "Recording failed: ${e.message}"
                }
            }
        }
    }

    fun stopRecording() {
        isRecording = false
        audioRecorder.stopRecording()
        isTranscribing = true

        viewModelScope.launch(Dispatchers.IO) {
            currentAudioFile?.let { file ->
                // Re‑init if model path changed
                if (!isInitialized || currentModelPath != getModelFilePath()) {
                    val newPath = getModelFilePath()
                    if (whisperBridge.initialize(newPath)) {
                        currentModelPath = newPath
                        isInitialized = true
                    } else {
                        withContext(Dispatchers.Main) {
                            isTranscribing = false
                            errorMessage = "Model not available."
                        }
                        return@launch
                    }
                }

                val langCode = toWhisperCode(currentLanguage.value)
                val result = whisperBridge.transcribe(
                    file.absolutePath,
                    langCode,
                    isTranscribeMode
                )
                withContext(Dispatchers.Main) {
                    transcriptionText = result
                    isTranscribing = false
                }
            } ?: run {
                withContext(Dispatchers.Main) {
                    isTranscribing = false
                    transcriptionText = "No audio recorded"
                }
            }
        }
    }

    fun saveTranscription() {
        if (transcriptionText.isBlank()) return
        viewModelScope.launch(Dispatchers.IO) {
            val dateStr = SimpleDateFormat("yyyy-MM-dd_HH-mm-ss", Locale.getDefault()).format(Date())
            val fileName = "Note_$dateStr.txt"
            repository.saveNote(fileName, transcriptionText)
            withContext(Dispatchers.Main) {
                transcriptionText = ""
            }
        }
    }

    fun loadNoteContent(note: NoteFile) {
        viewModelScope.launch(Dispatchers.IO) {
            val content = repository.readNote(note.fileName)
            withContext(Dispatchers.Main) {
                selectedNote = note.copy(content = content)
            }
        }
    }

    fun deleteNote(note: NoteFile) {
        viewModelScope.launch(Dispatchers.IO) {
            repository.deleteNote(note.fileName)
            if (selectedNote?.fileName == note.fileName) {
                withContext(Dispatchers.Main) {
                    selectedNote = null
                }
            }
        }
    }

    fun clearSelection() {
        selectedNote = null
    }

    fun clearError() {
        errorMessage = ""
    }

    private fun getModelFilePath(): String =
        File(modelsDir, "ggml-${currentModel.value}.bin").absolutePath

    private fun toWhisperCode(lang: String): String = when (lang) {
        "English" -> "en"
        "Mandarin" -> "zh"
        "Japanese" -> "ja"
        "Korean" -> "ko"
        "Indonesian" -> "id"
        else -> "en"
    }
}
