#include <jni.h>
#include <string>
#include <vector>
#include <fstream>
#include <mutex>

#include "whisper.h"

static struct whisper_context* g_ctx = nullptr;
static std::mutex g_mutex;

// Improved WAV loader – skips extra chunks to find "data"
static std::vector<float> load_wav(const std::string& fname) {
    std::ifstream file(fname, std::ios::binary);
    if (!file.is_open()) return {};

    // Read RIFF header
    char riff[4];
    file.read(riff, 4);
    if (file.gcount() != 4 || std::string(riff, 4) != "RIFF") return {};
    file.ignore(4); // file size
    char wave[4];
    file.read(wave, 4);
    if (file.gcount() != 4 || std::string(wave, 4) != "WAVE") return {};

    int16_t bitsPerSample = 16;
    uint32_t dataSize = 0;
    bool dataFound = false;

    // Scan chunks until we find "data"
    while (file.good()) {
        char chunkId[4];
        file.read(chunkId, 4);
        if (file.gcount() != 4) break;
        uint32_t chunkSize;
        file.read(reinterpret_cast<char*>(&chunkSize), 4);
        if (std::string(chunkId, 4) == "fmt ") {
            // Read format chunk
            std::vector<char> fmt(chunkSize);
            file.read(fmt.data(), chunkSize);
            if (chunkSize >= 14) {
                bitsPerSample = *reinterpret_cast<int16_t*>(fmt.data() + 14);
            }
        } else if (std::string(chunkId, 4) == "data") {
            dataSize = chunkSize;
            dataFound = true;
            break;
        } else {
            file.ignore(chunkSize); // skip unknown chunks
        }
    }

    if (!dataFound || bitsPerSample != 16) return {};

    // Read PCM data
    std::vector<int16_t> pcm16(dataSize / 2);
    file.read(reinterpret_cast<char*>(pcm16.data()), dataSize);

    std::vector<float> pcmf(pcm16.size());
    for (size_t i = 0; i < pcm16.size(); ++i) {
        pcmf[i] = pcm16[i] / 32768.0f;
    }
    return pcmf;
}

extern "C" {

JNIEXPORT jboolean JNICALL
Java_com_noteflowai_app_whisper_WhisperBridge_initialize(
    JNIEnv *env,
    jobject /* this */,
    jstring modelFilePath) {

    std::lock_guard<std::mutex> lock(g_mutex);
    if (g_ctx) {
        whisper_free(g_ctx);
        g_ctx = nullptr;
    }

    const char* path = env->GetStringUTFChars(modelFilePath, nullptr);
    g_ctx = whisper_init_from_file(path);
    env->ReleaseStringUTFChars(modelFilePath, path);

    return g_ctx != nullptr ? JNI_TRUE : JNI_FALSE;
}

JNIEXPORT jstring JNICALL
Java_com_noteflowai_app_whisper_WhisperBridge_transcribe(
    JNIEnv *env,
    jobject /* this */,
    jstring audioFilePath,
    jstring language,
    jboolean transcribe) {

    if (!g_ctx) {
        return env->NewStringUTF("[Error: Whisper not initialized]");
    }

    const char* audioPath = env->GetStringUTFChars(audioFilePath, nullptr);
    const char* langCode = env->GetStringUTFChars(language, nullptr);

    std::vector<float> pcmf = load_wav(audioPath);
    env->ReleaseStringUTFChars(audioFilePath, audioPath);

    if (pcmf.empty()) {
        env->ReleaseStringUTFChars(language, langCode);
        return env->NewStringUTF("[Error: failed to load audio]");
    }

    whisper_full_params params = whisper_full_default_params(WHISPER_SAMPLING_GREEDY);
    params.translate = !transcribe;
    params.language = langCode;
    params.print_realtime = false;
    params.print_progress = false;
    params.print_timestamps = false;
    params.no_context = false;

    std::lock_guard<std::mutex> lock(g_mutex);
    if (whisper_full(g_ctx, params, pcmf.data(), pcmf.size()) != 0) {
        env->ReleaseStringUTFChars(language, langCode);
        return env->NewStringUTF("[Error: transcription failed]");
    }

    const int n_segments = whisper_full_n_segments(g_ctx);
    std::string result;
    for (int i = 0; i < n_segments; ++i) {
        const char* text = whisper_full_get_segment_text(g_ctx, i);
        result += text;
        if (i < n_segments - 1) result += "\n";
    }
    if (!result.empty() && result.back() == '\n') result.pop_back();

    env->ReleaseStringUTFChars(language, langCode);
    return env->NewStringUTF(result.c_str());
}

JNIEXPORT void JNICALL
Java_com_noteflowai_app_whisper_WhisperBridge_release(
    JNIEnv *env,
    jobject /* this */) {

    std::lock_guard<std::mutex> lock(g_mutex);
    if (g_ctx) {
        whisper_free(g_ctx);
        g_ctx = nullptr;
    }
}

} // extern "C"
