package com.noteflowai.app.viewmodel

import android.app.Application
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.noteflowai.app.data.AudioRecorderHelper
import com.noteflowai.app.data.AudioRecording
import com.noteflowai.app.data.NoteFile
import com.noteflowai.app.data.NoteRepository
import com.noteflowai.app.data.RecordingRepository
import com.noteflowai.app.whisper.WhisperBridge
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileOutputStream
import java.text.SimpleDateFormat
import java.util.*

class MainViewModel(application: Application) : AndroidViewModel(application) {

    private val noteRepository = NoteRepository(application)
    private val recordingRepository = RecordingRepository(application)
    private val whisperBridge = WhisperBridge()
    private val audioRecorder = AudioRecorderHelper()

    // Whisper engine state
    var isInitialized by mutableStateOf(false)
        private set
    var isModelLoading by mutableStateOf(false)
        private set
    var errorMessage by mutableStateOf("")
        private set

    // Recording audio (not automatic transcription)
    var isRecording by mutableStateOf(false)
        private set
    var currentRecordingFileName by mutableStateOf("")
        private set

    // Saved audio recordings
    val savedRecordings: StateFlow<List<AudioRecording>> = recordingRepository.recordingsFlow

    // Transcription state (triggered manually)
    var isTranscribing by mutableStateOf(false)
        private set
    var transcribedText by mutableStateOf("")
        private set
    var activeTranscriptionRecording by mutableStateOf<AudioRecording?>(null)
        private set

    // Settings
    val currentModel = mutableStateOf("tiny")
    val currentLanguage = mutableStateOf("English")
    var isTranscribeMode by mutableStateOf(true)
        private set

    // Notes (unchanged)
    val savedNotes: StateFlow<List<NoteFile>> = noteRepository.notesFlow
    val savedNotesCount = mutableStateOf(0)
    var selectedNote by mutableStateOf<NoteFile?>(null)
        private set

    private var currentAudioFile: File? = null
    private var currentModelPath: String = ""
    private val modelsDir = File(application.filesDir, "models").also { it.mkdirs() }

    init {
        viewModelScope.launch {
            noteRepository.notesFlow.collect { notes -> savedNotesCount.value = notes.size }
        }
        loadDefaultModel()
    }

    // ---- Model management (unchanged) ----
    private fun loadDefaultModel() {
        viewModelScope.launch {
            withContext(Dispatchers.IO) {
                if (!copyModelFromAssets(currentModel.value)) {
                    withContext(Dispatchers.Main) {
                        isInitialized = false
                        errorMessage = "Whisper model file not found. Please add ggml-${currentModel.value}.bin to assets/models/"
                    }
                    return@withContext
                }
                initEngine()
            }
        }
    }

    private suspend fun copyModelFromAssets(model: String): Boolean {
        val assetPath = "models/ggml-$model.bin"
        val destFile = File(modelsDir, "ggml-$model.bin")
        if (destFile.exists()) {
            currentModelPath = destFile.absolutePath
            return true
        }
        return try {
            getApplication<Application>().assets.open(assetPath).use { input ->
                FileOutputStream(destFile).use { output -> input.copyTo(output) }
            }
            currentModelPath = destFile.absolutePath
            true
        } catch (e: Exception) {
            false
        }
    }

    private suspend fun initEngine() {
        withContext(Dispatchers.IO) {
            if (currentModelPath.isEmpty()) return@withContext
            val ok = whisperBridge.initialize(currentModelPath)
            withContext(Dispatchers.Main) {
                isInitialized = ok
                if (!ok) errorMessage = "Failed to load Whisper model."
                else errorMessage = ""
            }
        }
    }

    fun setModel(model: String) {
        currentModel.value = model
        viewModelScope.launch {
            isModelLoading = true
            withContext(Dispatchers.IO) {
                if (!copyModelFromAssets(model)) {
                    withContext(Dispatchers.Main) {
                        errorMessage = "Model file for $model not found."
                        isModelLoading = false
                    }
                    return@withContext
                }
                initEngine()
                isModelLoading = false
            }
        }
    }

    fun setLanguage(language: String) { currentLanguage.value = language }
    fun setMode(transcribe: Boolean) { isTranscribeMode = transcribe }

    // ---- Audio recording (no auto‑transcription) ----
    fun startRecording() {
        if (!isInitialized) {
            errorMessage = "Whisper engine not ready."
            return
        }
        isRecording = true
        val dateStr = SimpleDateFormat("yyyy-MM-dd_HH-mm-ss", Locale.getDefault()).format(Date())
        currentRecordingFileName = "audio_$dateStr.wav"
        currentAudioFile = File(getApplication<Application>().cacheDir, "temp_$currentRecordingFileName")

        viewModelScope.launch(Dispatchers.IO) {
            try {
                audioRecorder.startRecording(currentAudioFile!!)
            } catch (e: Exception) {
                withContext(Dispatchers.Main) {
                    isRecording = false
                    errorMessage = "Recording failed: ${e.message}"
                }
            }
        }
    }

    fun stopRecording() {
        isRecording = false
        audioRecorder.stopRecording()

        viewModelScope.launch(Dispatchers.IO) {
            // Save the recorded file to the recordings directory
            currentAudioFile?.let { tempFile ->
                recordingRepository.saveRecording(tempFile, currentRecordingFileName)
                tempFile.delete() // clean cache
            }
        }
    }

    // ---- Manual transcription of a saved recording ----
    fun transcribeRecording(recording: AudioRecording) {
        activeTranscriptionRecording = recording
        transcribedText = ""
        isTranscribing = true

        viewModelScope.launch(Dispatchers.IO) {
            // Ensure engine is ready with current model
            if (!isInitialized || currentModelPath != getModelFilePath()) {
                val newPath = getModelFilePath()
                if (whisperBridge.initialize(newPath)) {
                    currentModelPath = newPath
                    isInitialized = true
                } else {
                    withContext(Dispatchers.Main) {
                        isTranscribing = false
                        errorMessage = "Model not available."
                    }
                    return@launch
                }
            }

            val langCode = toWhisperCode(currentLanguage.value)
            val result = whisperBridge.transcribe(
                recording.filePath,
                langCode,
                isTranscribeMode
            )
            withContext(Dispatchers.Main) {
                transcribedText = result
                isTranscribing = false
                activeTranscriptionRecording = recording
            }
        }
    }

    // ---- Save transcription as note ----
    fun saveTranscriptionAsNote() {
        if (transcribedText.isBlank()) return
        viewModelScope.launch(Dispatchers.IO) {
            val dateStr = SimpleDateFormat("yyyy-MM-dd_HH-mm-ss", Locale.getDefault()).format(Date())
            val fileName = "Note_$dateStr.txt"
            noteRepository.saveNote(fileName, transcribedText)
            withContext(Dispatchers.Main) {
                transcribedText = ""
                activeTranscriptionRecording = null
            }
        }
    }

    // ---- Delete a saved recording ----
    fun deleteRecording(recording: AudioRecording) {
        viewModelScope.launch(Dispatchers.IO) {
            recordingRepository.deleteRecording(recording.fileName)
            if (activeTranscriptionRecording?.fileName == recording.fileName) {
                withContext(Dispatchers.Main) {
                    activeTranscriptionRecording = null
                    transcribedText = ""
                }
            }
        }
    }

    // ---- Notes management (unchanged) ----
    fun loadNoteContent(note: NoteFile) {
        viewModelScope.launch(Dispatchers.IO) {
            val content = noteRepository.readNote(note.fileName)
            withContext(Dispatchers.Main) { selectedNote = note.copy(content = content) }
        }
    }

    fun deleteNote(note: NoteFile) {
        viewModelScope.launch(Dispatchers.IO) {
            noteRepository.deleteNote(note.fileName)
            if (selectedNote?.fileName == note.fileName) {
                withContext(Dispatchers.Main) { selectedNote = null }
            }
        }
    }

    fun clearSelection() { selectedNote = null }
    fun clearError() { errorMessage = "" }

    private fun getModelFilePath(): String = File(modelsDir, "ggml-${currentModel.value}.bin").absolutePath

    private fun toWhisperCode(lang: String): String = when (lang) {
        "English" -> "en"
        "Mandarin" -> "zh"
        "Japanese" -> "ja"
        "Korean" -> "ko"
        "Indonesian" -> "id"
        else -> "en"
    }
}
