package com.noteflowai.app.ui.screens

import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Delete
import androidx.compose.material.icons.filled.Mic
import androidx.compose.material.icons.filled.Stop
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import com.noteflowai.app.data.AudioRecording
import com.noteflowai.app.viewmodel.MainViewModel

@Composable
fun RecordScreen(viewModel: MainViewModel) {
    val isRecording by viewModel.isRecording
    val isInitialized by viewModel.isInitialized
    val isModelLoading by viewModel.isModelLoading
    val errorMessage by viewModel.errorMessage
    val recordings by viewModel.savedRecordings

    val isTranscribing by viewModel.isTranscribing
    val transcribedText by viewModel.transcribedText
    val activeRecording by viewModel.activeTranscriptionRecording

    // State for transcribe/translate dialog
    var showTranscribeDialog by remember { mutableStateOf(false) }
    var selectedRecordingForTranscribe by remember { mutableStateOf<AudioRecording?>(null) }

    // Error Snackbar host
    val snackbarHostState = remember { SnackbarHostState() }
    LaunchedEffect(errorMessage) {
        if (errorMessage.isNotEmpty()) {
            snackbarHostState.showSnackbar(errorMessage)
            viewModel.clearError()
        }
    }

    Scaffold(
        snackbarHost = { SnackbarHost(snackbarHostState) }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Record button
            FloatingActionButton(
                onClick = { if (isRecording) viewModel.stopRecording() else viewModel.startRecording() },
                modifier = Modifier.size(64.dp),
                containerColor = if (isRecording) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary
            ) {
                Icon(
                    imageVector = if (isRecording) Icons.Default.Stop else Icons.Default.Mic,
                    contentDescription = if (isRecording) "Stop" else "Record",
                    tint = MaterialTheme.colorScheme.onPrimary
                )
            }

            if (!isInitialized) {
                if (isModelLoading) {
                    CircularProgressIndicator(modifier = Modifier.padding(8.dp))
                }
                Text(
                    text = if (isModelLoading) "Loading model…" else "Engine not ready",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                )
                Spacer(modifier = Modifier.height(16.dp))
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Saved recordings list
            if (recordings.isEmpty()) {
                Text("No recordings yet", style = MaterialTheme.typography.bodyLarge)
            } else {
                Text("Saved Recordings", style = MaterialTheme.typography.titleMedium)
                Spacer(modifier = Modifier.height(8.dp))
                LazyColumn(modifier = Modifier.weight(1f)) {
                    items(recordings, key = { it.fileName }) { rec ->
                        RecordingItem(
                            recording = rec,
                            onClick = {
                                selectedRecordingForTranscribe = rec
                                showTranscribeDialog = true
                            },
                            onDelete = { viewModel.deleteRecording(rec) }
                        )
                    }
                }
            }
        }
    }

    // Dialog to choose transcribe/translate
    if (showTranscribeDialog && selectedRecordingForTranscribe != null) {
        AlertDialog(
            onDismissRequest = { showTranscribeDialog = false },
            title = { Text("Transcribe Audio") },
            text = {
                Column {
                    Text("Choose mode for: ${selectedRecordingForTranscribe!!.fileName}")
                    if (isTranscribing && activeRecording == selectedRecordingForTranscribe) {
                        LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
                        Text("Processing…", style = MaterialTheme.typography.bodySmall)
                    }
                    if (transcribedText.isNotEmpty() && activeRecording == selectedRecordingForTranscribe) {
                        Text("Result:")
                        Text(transcribedText, style = MaterialTheme.typography.bodyMedium)
                    }
                }
            },
            confirmButton = {
                TextButton(onClick = {
                    viewModel.transcribeRecording(selectedRecordingForTranscribe!!)
                }) {
                    Text("Transcribe")
                }
            },
            dismissButton = {
                TextButton(onClick = {
                    viewModel.setMode(false) // translate mode
                    viewModel.transcribeRecording(selectedRecordingForTranscribe!!)
                }) {
                    Text("Translate → EN")
                }
            }
        )
    }
}

@Composable
fun RecordingItem(recording: AudioRecording, onClick: () -> Unit, onDelete: () -> Unit) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() }
    ) {
        Row(
            modifier = Modifier.padding(16.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Text(text = recording.fileName, style = MaterialTheme.typography.titleMedium)
                Text(
                    text = recording.lastModified,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                )
            }
            IconButton(onClick = onDelete) {
                Icon(Icons.Default.Delete, contentDescription = "Delete", tint = MaterialTheme.colorScheme.error)
            }
        }
    }
}
